import io,json,sys
from pathlib import Path
from types import SimpleNamespace as NS
from unittest.mock import patch
from training.holistic_migration import webcam,camera
results=[]
for stage in (None,'write','flush','close'):
    calls=[]
    primary=camera.CaptureError('original source failure sentinel')
    primary.__cause__=EOFError('original wire EOF sentinel')
    secondary=OSError('operational report '+str(stage)+' sentinel')
    class Stream:
        def write(self, text):
            calls.append('report.write')
            if stage=='write':raise secondary
            self.payload=text
        def flush(self):
            calls.append('report.flush')
            if stage=='flush':raise secondary
        def close(self):
            calls.append('report.close')
            if stage=='close':raise secondary
    stream=Stream()
    class Capture:
        metadata=dict(protocol=1,width=2,height=1,frame_bytes=8,pixel_format='BGRA',device_type=camera.BUILTIN_TYPE,continuity=False,device_sha256='a'*64)
        received=1;dropped=0;stderr_tail=b'';process=NS(returncode=7)
        def next_frame(self,deadline):raise primary
        def close(self):calls.append('capture.close')
        def raise_if_failed(self):raise primary
    class Detector:
        def close(self):calls.append('detector.close')
    class CV:
        WINDOW_AUTOSIZE=1
        def namedWindow(self,*a):calls.append('window.create')
        def destroyWindow(self,*a):calls.append('window.close')
    binding=NS(source_sha256='b'*64,binary_sha256='c'*64,receipt=Path('/synthetic/binding.json'))
    runtime=NS(build=lambda p:binding,capture=lambda *a,**k:Capture(),detector=lambda p:Detector(),cv=CV(),clock=lambda:0.,detector_version='synthetic',gui_version='synthetic')
    options=webcam.Options(Path('/synthetic/official.task'),Path('/synthetic/build'),1.,Path('/synthetic/report.json'))
    with patch.object(webcam,'validate_options'),patch.object(camera,'digest',return_value='d'*64),patch.object(Path,'open',return_value=stream):
        try:webcam.run_preview(options,runtime=runtime)
        except BaseException as e:
            observed=e
        else:raise AssertionError('source fault must never return normally')
    row=dict(stage=stage,raised_type=type(observed).__name__,raised_message=str(observed),is_original_source_primary=observed is primary,cause_type=type(observed.__cause__).__name__ if observed.__cause__ else None,context_type=type(observed.__context__).__name__ if observed.__context__ else None,calls=calls)
    assert calls[:4]==['window.create','capture.close','detector.close','window.close']
    if stage is None:assert observed is primary
    else:assert observed is secondary and observed.__cause__ is None and observed.__context__ is None
    results.append(row)
print(json.dumps(results))

