import contextlib,io,json,os,subprocess,sys,time
from pathlib import Path
from types import SimpleNamespace as NS
from unittest.mock import patch
from training.holistic_migration import webcam,camera
metadata=dict(protocol=1,width=2,height=1,frame_bytes=8,pixel_format='BGRA',device_type=camera.BUILTIN_TYPE,continuity=False,device_sha256='a'*64)
child_code='import os,sys;os.write(1,sys.argv[1].encode()+b"\\n");os.write(2,b"synthetic native diagnostic\\n");sys.exit(7)'
results=[]
for stage in (None,'write','flush','close'):
    calls=[];captures=[];children=[];first=[]
    secondary=OSError('operational report '+str(stage)+' sentinel')
    class Stream:
        def write(self,text):
            calls.append('report.write')
            if stage=='write':raise secondary
            self.payload=text
        def flush(self):
            calls.append('report.flush')
            if stage=='flush':raise secondary
        def close(self):
            calls.append('report.close')
            if stage=='close':raise secondary
    stream=Stream()
    def spawn(command,**kwargs):
        child=subprocess.Popen([sys.executable,'-E','-B','-c',child_code,json.dumps(metadata)],**kwargs)
        children.append(child);return child
    def make_capture(binding,**kwargs):
        with patch.object(camera,'verify_binding'):
            capture=camera.OwnedCapture(binding,popen=spawn,**kwargs)
        captures.append(capture)
        original=capture.next_frame
        def next_frame(deadline):
            try:return original(deadline)
            except BaseException as e:first.append(e);raise
        capture.next_frame=next_frame
        return capture
    class Detector:
        def close(self):calls.append('detector.close')
    class CV:
        WINDOW_AUTOSIZE=1
        def namedWindow(self,*a):calls.append('window.create')
        def destroyWindow(self,*a):calls.append('window.close')
    binding=NS(binary=Path(sys.executable),source_sha256='b'*64,binary_sha256='c'*64,receipt=Path('/synthetic/binding.json'))
    runtime=NS(build=lambda p:binding,capture=make_capture,detector=lambda p:Detector(),cv=CV(),clock=time.monotonic,detector_version='synthetic',gui_version='synthetic')
    options=webcam.Options(Path('/synthetic/official.task'),Path('/synthetic/build'),1.,Path('/synthetic/report.json'))
    stderr=io.StringIO()
    try:
        with contextlib.redirect_stderr(stderr),patch.object(webcam,'validate_options'),patch.object(camera,'digest',return_value='d'*64),patch.object(Path,'open',return_value=stream):
            try:webcam.run_preview(options,runtime=runtime)
            except BaseException as e:observed=e
            else:raise AssertionError('source failure must not return normally')
        capture=captures[0]
        assert len(first)==1 and isinstance(first[0],camera.CaptureError)
        assert isinstance(capture.error,EOFError) and capture.process.returncode==7
        assert capture.process.stdout.closed and capture.process.stderr.closed
        assert not capture.reader_thread.is_alive() and not capture.stderr_thread.is_alive()
        assert 'synthetic native diagnostic' in stderr.getvalue()
        if stage is None:assert observed is first[0] and observed.__cause__ is capture.error
        else:assert observed is secondary and observed.__cause__ is None and observed.__context__ is None
        results.append(dict(stage=stage,source_error=type(capture.error).__name__,native_exit=capture.process.returncode,original_exception_type=type(first[0]).__name__,raised_type=type(observed).__name__,raised_message=str(observed),original_primary_preserved=observed is first[0],cause_type=type(observed.__cause__).__name__ if observed.__cause__ else None,context_type=type(observed.__context__).__name__ if observed.__context__ else None,stdout_closed=capture.process.stdout.closed,stderr_closed=capture.process.stderr.closed,threads_stopped=True,detector_closed='detector.close' in calls,window_closed='window.close' in calls,stderr_retained=True,calls=calls))
    finally:
        for child in children:
            if child.poll() is None:child.kill();child.wait(timeout=2)
            for pipe in (child.stdout,child.stderr):
                if not pipe.closed:pipe.close()
        for capture in captures:
            capture.stop.set()
            for thread in (capture.reader_thread,capture.stderr_thread):
                if thread is not None and thread.ident is not None:thread.join(timeout=2)
print(json.dumps(results))
